-                                 copyInParams, padParams);
-        }
-    } else {
-        copyInParams.blockCount = 1;
-        copyInParams.blockLen = getLen * sizeof(half);
-        copyInParams.srcStride = 0;
-        copyInParams.dstStride = 0;
-        copyInParams.rsv = 0;
