-
-    if (assignContext.curBN2Idx / numHeadsK_ != assignContext.curBIdx) {
-        assignContext.curBIdx = assignContext.curBN2Idx / numHeadsK_;
-        assignContext.curS1GIdx = 0U;
-        UpdateBatch = true;
